    pos: { ...entity.pos },
    vel: entity.vel && vecUsable(entity.vel) ? { ...entity.vel } : { x: 0, y: 0, z: 0 },
    quat:
      entity.rot && quatUsable(entity.rot) ? { ...entity.rot } : { x: 0, y: 0, z: 0, w: 1 },
    regime: 'space',
  };
